+  cpSync(SEAT_MAP, join(root, ".agents", "SYSTEM", "hub-partner-seats.json"));
+  if (agentName) writeFileSync(join(root, ".agents", "AGENT.local.md"), `---\nname: ${agentName}\nrole: developer\npartner: Atlas\n---\n`);
